const typeLabels={conquest:'军事灭国',replacement:'王朝取代',surrender:'纳土归降',collapse:'政权崩溃',coalition:'联合灭国'};
function matches(feature,names,aliases){const t=feature.properties.title;return names.some(n=>(aliases[n]||[n]).includes(t));}
function references(event,frames,aliases){const before=[...frames].reverse().find(f=>f.year<event.year)||null;const after=frames.find(f=>f.year>=event.year)||frames.at(-1);return {before,after};}
